public class InterviewWorkflowTests {
 sealed class State(string name="recruiter"):AuthenticationStateProvider{public override Task<AuthenticationState> GetAuthenticationStateAsync()=>Task.FromResult(new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity([new(ClaimTypes.Name,name),new(ClaimTypes.NameIdentifier,name),new(ClaimTypes.Role,"Recruiter")],"Test"))));}
 sealed class Factory(DbContextOptions<AtsDbContext> options):IDbContextFactory<AtsDbContext>{public AtsDbContext CreateDbContext()=>new(options);}
 sealed class Mail:IAccountEmail{public bool Configured{get;set;}=true;public bool Fail;public List<string> Bodies=[];public Task Send(string email,string subject,string body){if(Fail)throw new InvalidOperationException();Bodies.Add(email+"\n"+body);return Task.CompletedTask;}}
 sealed class Fixture:IAsyncDisposable {
  public SqliteConnection Db=new("Data Source=:memory:");public Factory Factory=null!;public Mail Mail=new();public RecruitmentUpdates Updates=new();public Access Access=null!;public InterviewService Interviews=null!;public HiringReviewService Review=null!;public Guid ApplicationId;public string ReviewCookie="";public ClientContact Contact=new(){Name="Manager",Email="manager@client.test"};public IDataProtectionProvider Protection=new EphemeralDataProtectionProvider();public IConfiguration Config=null!;
  public async Task Init(bool local=false){await Db.OpenAsync();Factory=new(new DbContextOptionsBuilder<AtsDbContext>().UseSqlite(Db).Options);await using var db=Factory.CreateDbContext();await DatabaseInitializer.InitializeAsync(db);db.Users.Add(new(){Id="recruiter",UserName="recruiter"});db.Roles.Add(new("Recruiter"){Id="r"});db.UserRoles.Add(new(){UserId="recruiter",RoleId="r"});var client=new Client{Name="Test Client",NormalizedName="TEST CLIENT"};Contact.ClientId=client.Id;db.Add(client);db.Add(Contact);var p=new Position{Reference="INT-001",Title="HR Manager",ClientId=client.Id,Client=client.Name,AssignedRecruiter="recruiter"};db.Add(p);var c=new Candidate{Name="Interview Candidate",Email="candidate@private.test"};db.Add(c);var a=new Assessment{PositionId=p.Id,CandidateId=c.Id,State="Saved",CandidateName=c.Name,SnapshotJson=JsonSerializer.Serialize(new AssessmentSnapshot(c,null,[],"","","",client.Name,p.Title,p.Reference))};db.Add(a);ApplicationId=a.Id;await db.SaveChangesAsync();Config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Review:PublicBaseUrl",local?"":"https://ats.example.test"}}).Build();Access=new(new State(),Factory);Review=new(Factory,Access,Protection,Config,Mail,Updates);Interviews=new(Factory,Access,Protection,Config,Mail,Updates);var link=await Review.Forward(Contact.Id,[a.Id],"",false);ReviewCookie=(await Review.Exchange(Token(link.Link)))!.Value.Cookie;}
  public static string Token(string link)=>QueryHelpers.ParseQuery(new Uri(link).Query)["token"].ToString();
  public async Task<InterviewInvite> Input(){await using var db=Factory.CreateDbContext();var a=await db.Assessments.SingleAsync();var i=await db.InterviewBookings.OrderByDescending(i=>i.CreatedUtc).FirstOrDefaultAsync();return new(a.Id,a.Revision,i?.Id,i?.Revision,"candidate@private.test",Contact.Email,DateTime.UtcNow.AddDays(3).ToString("yyyy-MM-ddTHH:mm"),"UTC",45,"Online","Zoom","https://zoom.us/j/123456","","Please Confirm Your Availability.");}
  public async Task<(InterviewBooking Booking,string Cookie)> Invite(){var result=await Interviews.Invite(await Input());return ((await Interviews.Details(ApplicationId))!,(await Interviews.Exchange(Token(result.Link)))!.Value.Cookie);}
  public async Task<HiringRow> Row()=>Assert.Single((await Review.Read(ReviewCookie)).Rows);
  public ValueTask DisposeAsync()=>Db.DisposeAsync();
 }

 [Theory][InlineData("Asia/Karachi","+05:00")][InlineData("America/New_York","-05:00")][InlineData("Asia/Kolkata","+05:30")]
 public void TimeZoneLabelsShowSignedOffsets(string zone,string expected){Assert.Contains("UTC"+expected,InterviewService.ZoneLabel(TimeZoneInfo.FindSystemTimeZoneById(zone),"2026-12-01T15:00"));}
 [Fact]public async Task WorkspacePlanControlsInvitationsAndOnlineAccessButKeepsManualUpdates(){
  await using var f=new Fixture();await f.Init();Guid workspaceId;
  await using(var db=f.Factory.CreateDbContext()){var w=new EmployerWorkspace{OwnerId="recruiter",Kind=AccountTypes.Freelance,SubscriptionName="Free",SubscriptionTermsJson=JsonSerializer.Serialize(new SubscriptionTerms())};workspaceId=w.Id;db.Add(w);var owner=await db.Users.SingleAsync(u=>u.Id=="recruiter");owner.AccountType=AccountTypes.Freelance;owner.EmailConfirmed=true;(await db.Positions.SingleAsync()).WorkspaceId=w.Id;await db.SaveChangesAsync();}
  Assert.False((await f.Interviews.CommunicationAccess(f.ApplicationId)).Invitations);
  var freeInput=await f.Input();await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Interviews.Invite(freeInput));
  await using(var db=f.Factory.CreateDbContext()){var a=await db.Assessments.SingleAsync();a.Stage="Hold";await new AtsService(f.Factory,f.Access).SaveLifecycle(a);}
  Assert.Empty(f.Mail.Bodies);
  await using(var db=f.Factory.CreateDbContext()){var w=await db.EmployerWorkspaces.SingleAsync();w.SubscriptionName="Starter";await db.SaveChangesAsync();}
  var permission=await f.Interviews.CommunicationAccess(f.ApplicationId);Assert.True(permission.Invitations);Assert.False(permission.Integrations);
  var input=await f.Input();await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Interviews.Invite(input));
  await f.Interviews.Invite(input with{Mode="On-Site",Location="Client office",Provider="Manual Link"});Assert.Contains(f.Mail.Bodies,b=>b.StartsWith("candidate@private.test"));
  await using(var db=f.Factory.CreateDbContext()){var w=await db.EmployerWorkspaces.SingleAsync();w.SubscriptionName="Free";await db.SaveChangesAsync();}
  f.Mail.Bodies.Clear();await using(var db=f.Factory.CreateDbContext()){var a=await db.Assessments.SingleAsync();await f.Interviews.Progress(a.Id,a.Revision,"Hold","");}
  Assert.DoesNotContain(f.Mail.Bodies,b=>b.StartsWith("candidate@private.test"));
 }
 [Fact]public async Task ManualMeetingInvitationDoesNotCountAsConfirmedUntilCandidateAccepts(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();Assert.Equal("Awaiting Confirmation",i.Status);Assert.Equal(2,f.Mail.Bodies.Count);Assert.Contains(f.Mail.Bodies,body=>body.Contains("candidate@private.test")&&body.Contains("/interview/access?token="));var row=await f.Row();Assert.Equal("Not Scheduled",row.InterviewStatus);Assert.Equal("Awaiting Confirmation",row.Interview!.Status);Assert.DoesNotContain("@private.test",JsonSerializer.Serialize(row));await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Accepted","",null,"UTC"));i=(await f.Interviews.Details(f.ApplicationId))!;Assert.Equal("Confirmed",i.Status);Assert.Equal("Scheduled",(await f.Row()).InterviewStatus);Assert.Equal("Confirmed",(await f.Row()).Interview!.Status);}
 [Fact]public async Task ProposedTimeRequiresManagerApprovalAndInvalidatesOldResponseLink(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();var proposed=DateTime.UtcNow.AddDays(4).ToString("yyyy-MM-ddTHH:mm");await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"New Time Proposed","Please Use This Time",proposed,"UTC"));i=(await f.Interviews.Details(f.ApplicationId))!;Assert.Equal("New Time Proposed",(await f.Row()).Interview!.Status);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Review.SharedApplication("bad",i.SubmissionId));Assert.Equal(f.ApplicationId,await f.Review.SharedApplication(f.ReviewCookie,i.SubmissionId));await f.Interviews.ReviewProposal(f.ApplicationId,i.Id,i.Revision,true,null,"UTC");i=(await f.Interviews.Details(f.ApplicationId))!;Assert.Equal("Confirmed",i.Status);Assert.Equal(InterviewService.ParseTime(proposed,"UTC"),i.StartUtc);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Interviews.Read(cookie));Assert.Equal("Scheduled",(await f.Row()).InterviewStatus);}
 [Fact]public async Task ManagerAlternativeTimeRequiresCandidateConfirmationAgain(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"New Time Proposed","",DateTime.UtcNow.AddDays(4).ToString("yyyy-MM-ddTHH:mm"),"UTC"));i=(await f.Interviews.Details(f.ApplicationId))!;await f.Interviews.ReviewProposal(f.ApplicationId,i.Id,i.Revision,false,DateTime.UtcNow.AddDays(5).ToString("yyyy-MM-ddTHH:mm"),"UTC");Assert.Equal("Awaiting Confirmation",(await f.Row()).Interview!.Status);Assert.Equal("Not Scheduled",(await f.Row()).InterviewStatus);}
 [Fact]public async Task DecliningInterviewDoesNotRejectCandidateAndExternalResponsesAreAudited(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.RecordResponse(new(i.Id,i.Revision,"Declined","Unavailable",null,"UTC"),"WhatsApp");var row=await f.Row();Assert.NotEqual("Rejected",row.Stage);Assert.Equal("Declined",row.Interview!.Status);Assert.Contains("WhatsApp",row.Interview.ResponseSource);var action=Assert.Single(await new RecruiterActionService(f.Factory,f.Access,f.Updates).Inbox());Assert.Equal("Arrange Interview",action.Action.Type);await Assert.ThrowsAsync<DbUpdateConcurrencyException>(()=>f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Accepted","",null,"UTC")));await using var db=f.Factory.CreateDbContext();Assert.Contains(await db.Audit.ToListAsync(),e=>e.Action=="Interview response"&&e.UserId=="recruiter");}
 [Fact]public async Task RejectedProfileDisappearsFromReviewButHistoryIsRetainedAndResubmissionIsExplicit(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();var row=await f.Row();await f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Reject","Not Suitable",null,"","",30,""));Assert.Empty((await f.Review.Read(f.ReviewCookie)).Rows);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Review.Reports(f.ReviewCookie,row.Id,null));await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Interviews.RecordResponse(new(i.Id,i.Revision,"Accepted","",null,"UTC"),"Phone"));await using var db=f.Factory.CreateDbContext();Assert.Equal(1,await db.HiringSubmissions.CountAsync());var a=await db.Assessments.SingleAsync();await f.Interviews.Reopen(a.Id,a.Revision);Assert.Empty((await f.Review.Read(f.ReviewCookie)).Rows);await f.Review.Forward(f.Contact.Id,[a.Id],"",false);Assert.Single((await f.Review.Read(f.ReviewCookie)).Rows);}
 [Fact]public async Task OnSiteInviteRequiresAddressAndUnsafeMeetingUrlsAreRejected(){await using var f=new Fixture();await f.Init();var input=await f.Input();await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Interviews.Invite(input with{MeetingLink="javascript:alert(1)"}));await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Interviews.Invite(input with{Mode="On-Site",Location=""}));await f.Interviews.Invite(input with{Mode="On-Site",Location="Office 2, Main Road. Arrive 10 Minutes Early."});var i=(await f.Interviews.Details(f.ApplicationId))!;Assert.Equal("",i.MeetingLink);Assert.Contains("Main Road",i.Location);}
 [Fact]public async Task LocalModeNeverPretendsAnEmailWasSentAndFailedEmailCanBeRetried(){await using var f=new Fixture();await f.Init(true);var result=await f.Interviews.Invite(await f.Input());Assert.Contains("Email Not Sent",result.Message);Assert.Empty(f.Mail.Bodies);Assert.Contains("Email Not Sent",await f.Interviews.DeliveryStatus((await f.Interviews.Details(f.ApplicationId))!.Id));await using var other=new Fixture();await other.Init();other.Mail.Fail=true;var (i,_)=await other.Invite();Assert.Contains("Failed",await other.Interviews.DeliveryStatus(i.Id));other.Mail.Fail=false;await other.Interviews.RetryDelivery(i.Id);Assert.Equal(2,other.Mail.Bodies.Count);await other.Interviews.RetryDelivery(i.Id);Assert.Equal(2,other.Mail.Bodies.Count);}
 [Fact]public async Task ResendingInvalidatesOldTokensAndStaleEditsCannotOverwriteNewerInvitation(){await using var f=new Fixture();await f.Init();var (_,cookie)=await f.Invite();var input=await f.Input();await f.Interviews.Invite(input with{MeetingLink="https://meet.google.com/abc-defg-hij",Provider="Google Meet"});await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>f.Interviews.Read(cookie));await Assert.ThrowsAsync<DbUpdateConcurrencyException>(()=>f.Interviews.Invite(input));var stranger=new InterviewService(f.Factory,new Access(new State("stranger"),f.Factory),f.Protection,f.Config,f.Mail,f.Updates);await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>stranger.Details(f.ApplicationId));}
 [Fact]public async Task PendingCandidateResponseCannotBeOverwrittenByOrdinaryManagerFeedback(){await using var f=new Fixture();await f.Init();await f.Invite();var row=await f.Row();await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Request Interview","",DateTime.UtcNow.AddDays(2).ToString("yyyy-MM-ddTHH:mm"),"UTC","Online",30,"")));}
 [Fact]public async Task CompletedRoundsRemainInHistoryAndManagerCanRecommendHireWithoutFinalizingIt(){await using var f=new Fixture();await f.Init();var (i,_)=await f.Invite();await using(var db=f.Factory.CreateDbContext()){var booking=await db.InterviewBookings.SingleAsync();booking.StartUtc=DateTime.UtcNow.AddHours(-2);booking.Status="Confirmed";var app=await db.Assessments.SingleAsync();app.InterviewStatus="Scheduled";await db.SaveChangesAsync();}var a=Assert.Single(await new AtsService(f.Factory,f.Access).Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Interview Completed","");var row=await f.Row();Assert.Equal("Completed",row.Interview!.Status);Assert.Equal("Awaiting Client Feedback",row.Stage);await f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Recommend Hire","Proceed With Offer",null,"","",30,""));Assert.NotEqual("Hired",(await f.Row()).Stage);Assert.Equal("Finalize Hiring",Assert.Single(await new RecruiterActionService(f.Factory,f.Access,f.Updates).Inbox()).Action.Type);a=Assert.Single(await new AtsService(f.Factory,f.Access).Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Hired","");Assert.Equal("Completed",(await f.Interviews.Details(a.Id))!.Status);}
 [Fact]public async Task NextInterviewRoundCreatesANewBookingAndKeepsThePreviousRound(){await using var f=new Fixture();await f.Init();await f.Invite();await using(var db=f.Factory.CreateDbContext()){var booking=await db.InterviewBookings.SingleAsync();booking.StartUtc=DateTime.UtcNow.AddHours(-2);booking.Status="Confirmed";await db.SaveChangesAsync();}var a=Assert.Single(await new AtsService(f.Factory,f.Access).Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Interview Completed","");a=Assert.Single(await new AtsService(f.Factory,f.Access).Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Next Round","");await f.Interviews.Invite(await f.Input());await using var check=f.Factory.CreateDbContext();Assert.Equal(2,await check.InterviewBookings.CountAsync());Assert.Equal(1,await check.InterviewBookings.CountAsync(i=>i.Status=="Completed"));Assert.Equal(1,await check.InterviewBookings.CountAsync(i=>i.Status=="Awaiting Confirmation"));}
 [Theory][InlineData("Send Offer")][InlineData("Request Interview")]
 public async Task InterviewerCanEvaluateConfirmedInterviewWithoutRecruiterCompletion(string outcome){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Accepted","",null,"UTC"));var row=await f.Row();Assert.Equal("Evaluate",row.ReviewAction);Assert.Equal("https://zoom.us/j/123456",row.Interview!.MeetingLink);Assert.Equal("Confirmed",row.Interview.Status);var feedback=new HiringFeedback(row.Id,row.Revision,row.ApplicationRevision,outcome,"Interview Completed Successfully",outcome=="Request Interview"?DateTime.UtcNow.AddDays(4).ToString("yyyy-MM-ddTHH:mm"):null,"UTC","Online",45,"",row.Interview.Revision,true);await f.Review.Reply(f.ReviewCookie,feedback);row=await f.Row();Assert.Equal("Completed",row.Interview!.Status);Assert.Equal(outcome=="Send Offer"?"Offer Requested":"Interview Requested",row.Stage);Assert.Equal(outcome=="Send Offer"?"Send Offer":"Arrange Interview",Assert.Single(await new RecruiterActionService(f.Factory,f.Access,f.Updates).Inbox()).Action.Type);await using var db=f.Factory.CreateDbContext();Assert.Contains(await db.Audit.ToListAsync(),e=>e.Action=="Interview completion confirmed");}
 [Fact]public async Task CandidateAcceptanceIsNotInterviewCompletionAndEvaluationChecksTheLatestBookingRevision(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Accepted","",null,"UTC"));var row=await f.Row();await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Send Offer","",null,"","",30,"",row.Interview!.Revision,false)));await Assert.ThrowsAsync<DbUpdateConcurrencyException>(()=>f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Send Offer","",null,"","",30,"",Guid.NewGuid(),true)));Assert.Equal("Confirmed",(await f.Row()).Interview!.Status);}
 [Fact]public async Task DeclinedAndProposedResponsesAlsoExposeEvaluationWithoutAllowingAnOffer(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Declined","Unavailable",null,"UTC"));var row=await f.Row();Assert.Equal("Evaluate",row.ReviewAction);await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Send Offer","",null,"","",30,"",row.Interview!.Revision,true)));}
 [Fact]public async Task InterviewerHoldAfterInterviewPreservesTheCompletedRound(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Accepted","",null,"UTC"));var row=await f.Row();await f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Hold","Discuss Internally",null,"","",30,"",row.Interview!.Revision,true));row=await f.Row();Assert.Equal("Hold",row.Stage);Assert.Equal("Completed",row.Interview!.Status);Assert.Empty(await new RecruiterActionService(f.Factory,f.Access,f.Updates).Inbox());}
 [Fact]public async Task RecruiterOfferAndHiringUpdatesKeepManagerInformedWithoutSendingAnAutomaticOfferLetter(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Accepted","",null,"UTC"));var row=await f.Row();await f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Send Offer","Proceed",null,"","",30,"",row.Interview!.Revision,true));f.Mail.Bodies.Clear();var a=Assert.Single(await new AtsService(f.Factory,f.Access).Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Offer Sent","");Assert.Contains(f.Mail.Bodies,b=>b.Contains("manager@client.test")&&b.Contains("Recruitment Update: Offer Sent"));Assert.DoesNotContain(f.Mail.Bodies,b=>b.StartsWith("candidate@private.test"));Assert.Equal("View Outcome",(await f.Row()).ReviewAction);a=Assert.Single(await new AtsService(f.Factory,f.Access).Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Hired","");Assert.Contains(f.Mail.Bodies,b=>b.Contains("Recruitment Update: Hired"));Assert.Equal("Hired",(await f.Row()).Stage);}
 [Fact]public async Task SavedHiringContactIsTheDefaultRecipientForInterviewUpdates(){await using var f=new Fixture();await f.Init();Assert.Equal(f.Contact.Email,await f.Interviews.DefaultManagerEmail(f.ApplicationId));await f.Interviews.Invite((await f.Input()) with{ManagerEmail=""});Assert.Equal(f.Contact.Email,(await f.Interviews.Details(f.ApplicationId))!.ManagerEmail);Assert.Contains(f.Mail.Bodies,b=>b.StartsWith(f.Contact.Email));}
 [Fact]public async Task OfferSentStaysInPipelineAndOfferCardUntilAFinalHiringDecision(){await using var f=new Fixture();await f.Init();var (i,cookie)=await f.Invite();await f.Interviews.Respond(cookie,new(i.Id,i.Revision,"Accepted","",null,"UTC"));var row=await f.Row();await f.Review.Reply(f.ReviewCookie,new(row.Id,row.Revision,row.ApplicationRevision,"Send Offer","Prepare Offer",null,"","",30,"",row.Interview!.Revision,true));var ats=new AtsService(f.Factory,f.Access);var a=Assert.Single(await ats.Assessments());var interview=(await f.Interviews.List()).First();Assert.True(PipelineWorkflow.MatchesCard(a,interview,"offer-requested",true));Assert.True(PipelineWorkflow.MatchesCard(a,interview,"action",true));await f.Interviews.Progress(a.Id,a.Revision,"Offer Sent","");a=Assert.Single(await ats.Assessments());interview=(await f.Interviews.List()).First();Assert.Equal("Saved",a.State);Assert.Equal("Offer Sent",PipelineWorkflow.CurrentStatus(a,true,interview));Assert.True(PipelineWorkflow.MatchesCard(a,interview,"",true));Assert.True(PipelineWorkflow.MatchesCard(a,interview,"offer-sent",true));Assert.False(PipelineWorkflow.MatchesCard(a,interview,"action",true));Assert.False(PipelineWorkflow.MatchesCard(a,interview,"offer-requested",true));Assert.False(PipelineWorkflow.IsFinal(a));Assert.Equal("Offer Sent",(await f.Row()).Stage);await f.Interviews.Progress(a.Id,a.Revision,"Hired","");a=Assert.Single(await ats.Assessments());Assert.True(PipelineWorkflow.MatchesCard(a,interview,"hired",true));Assert.False(PipelineWorkflow.MatchesCard(a,interview,"offer-sent",true));}
 [Fact]public async Task RejectedOfferMovesToRejectedHistoryWithoutDeletingTheCandidate(){await using var f=new Fixture();await f.Init();var ats=new AtsService(f.Factory,f.Access);var a=Assert.Single(await ats.Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Offer Sent","");a=Assert.Single(await ats.Assessments());await f.Interviews.Progress(a.Id,a.Revision,"Reject","Candidate Declined Offer");a=Assert.Single(await ats.Assessments());Assert.True(PipelineWorkflow.MatchesCard(a,null,"rejected",true));Assert.False(PipelineWorkflow.MatchesCard(a,null,"offer-sent",true));Assert.Equal("Saved",a.State);Assert.Single(await ats.Candidates());}
 [Theory][InlineData("Offer Requested","offer-requested")][InlineData("Offer Sent","offer-sent")][InlineData("Hired","hired")][InlineData("Rejected","rejected")]
 public void OfferAndOutcomeCardsRemainFindableWhenThePositionHasClosed(string stage,string key){var a=new Assessment{Stage=stage,Position=new(){Status="Closed"}};Assert.True(PipelineWorkflow.MatchesCard(a,null,key,true));Assert.True(PipelineWorkflow.MatchesCard(a,null,"",true));}
 [Fact]public void OfferStatusTakesPrecedenceOverAnOldInterviewStatus(){var a=new Assessment{Stage="Offer Sent",ClientStatus="Offer",Position=new(){Status="Active"}};var i=new InterviewSummary(Guid.NewGuid(),Guid.NewGuid(),a.Id,"Confirmed",DateTime.UtcNow.AddDays(1),30,"UTC","Online","Manual Link","https://meeting.test","",null,"","","");Assert.Equal("Offer Sent",PipelineWorkflow.CurrentStatus(a,true,i));Assert.True(PipelineWorkflow.MatchesCard(a,i,"offer-sent",true));Assert.False(PipelineWorkflow.MatchesCard(a,i,"upcoming",true));Assert.False(PipelineWorkflow.MatchesCard(a,i,"action",true,true));}
 [Theory][InlineData("Rejected")][InlineData("Hired")]public void TerminalOutcomesNeverBecomeUpcomingOrActionNeeded(string stage){var a=new Assessment{Stage=stage};var i=new InterviewSummary(Guid.NewGuid(),Guid.NewGuid(),a.Id,"Confirmed",DateTime.UtcNow.AddDays(1),30,"UTC","Online","Manual Link","https://meeting.test","",null,"","","");Assert.Equal(stage,PipelineWorkflow.CurrentStatus(a,true,i));Assert.False(PipelineWorkflow.ActionNeeded(a,i));}
}
